import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { uv, vec3, texture, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Vector2, Color } = ctx.THREE;

  // 1. Root group
  const group = new Group();

  // 2. Setup colors & sizes
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Dimensions of the card row
  const width = 5.0;
  const height = 1.25;

  // 3. Create a dark backdrop to prevent FLAT_VOID (Stage concept)
  // Ensures the element stands out with proper contrast
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.85
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.6);
  group.add(backdrop);

  // 4. Parallax Plane Geometry & Material (Tessellated Plane)
  const segments = 64;
  const cardGeo = new PlaneGeometry(width, height, segments, segments);
  const cardMat = new MeshBasicNodeMaterial({
    color: new Color(colors.paper),
    transparent: true,
    opacity: 1.0
  });

  // Load Main Texture & Depth Map
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((mainTex) => {
      mainTex.colorSpace = 'srgb';
      if (config.depthMapUrl) {
        ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
          // Shader Nodes: Displace local position based on depth map texture
          const uvNode = uv();
          const depthVal = texture(depthTex, uvNode).r;

          // Displace along the local normal vector (subtle, 0.15 scale)
          const displacementFactor = 0.15;
          const displacedPosition = positionLocal.add(normalLocal.mul(depthVal.mul(displacementFactor)));

          cardMat.positionNode = displacedPosition;
          cardMat.colorNode = texture(mainTex, uvNode);
          cardMat.needsUpdate = true;
        });
      } else {
        cardMat.colorNode = texture(mainTex);
        cardMat.needsUpdate = true;
      }
    }).catch((err) => {
      console.warn('Error loading parallax textures, falling back to surface color', err);
      cardMat.colorNode = vec3(new Color(colors.ink));
    });
  }

  // 5. Create Card Mesh & Subtle Accent Border (Machined Metal feel)
  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // Bottom edge divider (Horizontal row aesthetic)
  const dividerGeo = new PlaneGeometry(width, 0.02);
  const dividerMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.6
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -height / 2 - 0.05, 0.01);
  group.add(divider);

  // 6. Interactive Text Labels (Title and Meta text rendering via FontAtlas)
  const textGroup = new Group();
  textGroup.position.set(0, 0, 0.05);
  group.add(textGroup);

  const titleText = ctx.fontAtlas.createText('FEATURE SPECIFICATION', {
    fontSize: 0.2, // ~subhead unit
    color: colors.ink,
    align: 'left'
  });
  titleText.position.set(-width / 2 + 0.3, 0.1, 0.02);
  textGroup.add(titleText);

  const metaText = ctx.fontAtlas.createText('MODEL CLASSE-A // ATELIER', {
    fontSize: 0.09, // mono caption
    color: colors.accent,
    align: 'left'
  });
  metaText.position.set(-width / 2 + 0.3, -0.22, 0.02);
  textGroup.add(metaText);

  // 7. Interaction States (GSAP transitions & handlers)
  let isHovered = false;
  const timelines = [];

  const handlePointerOver = () => {
    if (isHovered) return;
    isHovered = true;

    const hoverTL = gsap.timeline();
    // Preset: rise-in subtle lift on hover
    hoverTL.to(cardMesh.position, { z: 0.15, duration: 0.4, ease: 'power2.out' }, 0);
    hoverTL.to(dividerMat, { opacity: 1.0, duration: 0.3 }, 0);
    timelines.push(hoverTL);
  };

  const handlePointerOut = () => {
    isHovered = false;
    const leaveTL = gsap.timeline();
    leaveTL.to(cardMesh.position, { z: 0, duration: 0.4, ease: 'power2.out' }, 0);
    leaveTL.to(dividerMat, { opacity: 0.6, duration: 0.3 }, 0);
    timelines.push(leaveTL);
  };

  const handlePointerDown = () => {
    const pressTL = gsap.timeline();
    // Press-down effect
    pressTL.to(cardMesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'power2.out' });
    pressTL.to(cardMesh.scale, { x: 1.0, y: 1.0, duration: 0.4, ease: 'back.out(2)' });
    timelines.push(pressTL);

    // Emit event & perform mock transition/navigation
    ctx.emit('hub-features.select', { id: 'parallax-stack' });
    ctx.emit('navigate', { to: 'hub-features' });
  };

  // Attach handlers
  group.userData.handlers = {
    pointerover: handlePointerOver,
    pointerout: handlePointerOut,
    pointerdown: handlePointerDown
  };

  // 8. Lifecycle cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
  };

  return group;
}
